        if not endpoint_results["adapt_router_mounted"]:
            print("   ❌ CRITICAL: Adaptive router may not be properly mounted")
            endpoint_results["routing_issues_identified"] = True
        
        # RECOMMENDATIONS
        print("\n💡 RECOMMENDATIONS:")
        
